import{Q as e,X as t,ft as n,n as r}from"./chunks/framework.SLwxmuMO.js";var i=JSON.parse(`{"title":"UI Operations Never Interrupt the User","description":"","frontmatter":{"id":"policy.0005","title":"UI Operations Never Interrupt the User","status":"active","established-by":"user.2026-11-07","supersedes":["policy.0004"]},"headers":[],"relativePath":"policies/0005-ui-no-interruption.md","filePath":"policies/0005-ui-no-interruption.md"}`),a={name:`policies/0005-ui-no-interruption.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="ui-operations-never-interrupt-the-user" tabindex="-1">UI Operations Never Interrupt the User <a class="header-anchor" href="#ui-operations-never-interrupt-the-user" aria-label="Permalink to “UI Operations Never Interrupt the User”">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h2><p>Recon works on the Mac someone is using. Whatever a <code>ui</code> operation inspects or does in an application, the person at that Mac must be able to carry on with what they are doing as if Recon were not running. This policy settles that once for every <code>ui</code> operation. It states only the behaviour the person experiences; how an operation achieves it belongs to the proposal that designs the operation. Earlier records and the code call this the no-focus contract.</p><h2 id="the-rule" tabindex="-1">The rule <a class="header-anchor" href="#the-rule" aria-label="Permalink to “The rule”">​</a></h2><p>Once a request&#39;s prerequisites are established, a <code>ui</code> operation must not interrupt what the person using the Mac is doing, and an operation that finds it has must fail with <code>UI_INTERFERENCE</code> rather than try to undo the interruption.</p><h2 id="why-this-exists" tabindex="-1">Why this exists <a class="header-anchor" href="#why-this-exists" aria-label="Permalink to “Why this exists”">​</a></h2><p>An agent investigating an application is useful only if the person can keep working while it does. Bringing the application forward, using it, and putting everything back looks harmless once the command returns, but for that moment the person&#39;s typing, clicking, or place on screen was taken from them. The interruption is the failure, and undoing it is a second interruption. A desktop that looks the same afterwards is no evidence that nothing happened while the operation ran.</p><p>The previous record, <a href="./0004-ui-no-focus">policy.0004</a>, stated this as a list of forbidden mechanisms. On 2026-11-07, while UI actions were being designed in <a href="./../proposals/0007-macos-ui-interaction">proposal.0007</a>, that list forbade changes inside a background application that the person never experiences. The owner directed that the policy state the behaviour that matters and leave mechanisms to the designs that meet it.</p><h2 id="what-it-applies-to" tabindex="-1">What it applies to <a class="header-anchor" href="#what-it-applies-to" aria-label="Permalink to “What it applies to”">​</a></h2><ul><li>Applies to: every <code>recon ui</code> operation that inspects or acts on an application, together with the work it does inside that application, from the moment the request&#39;s prerequisites are established until it returns. The person&#39;s experience is the test: what they are working in, where their typing and clicks go, where their pointer is, and which Space they are on stay theirs throughout.</li><li>Does not apply to: <ul><li>Changes inside the target application that the person does not experience, including the change an explicit action exists to make.</li><li>Changes the person makes themselves while an operation runs.</li><li>The setup prompts retained by <a href="./../decisions/0005-homebrew-ad-hoc-privacy-identity">decision.0005</a>. A missing privacy grant may request macOS authorization and then fail with <code>PERMISSION_DENIED</code>, and <code>ui session open --mode attach --allow-authorization</code> may raise the debugger-authorization dialog.</li><li><code>recon ui session prepare-host</code>, whose typed confirmation and <code>sudo</code> authentication interrupt by design.</li><li><code>recon app launch</code>, an explicitly activating command advertised as one.</li></ul></li></ul><p>No exception authorizes interrupting the person to make an operation work.</p><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li>Tier: task (Tier 1), with structural enforcement in the implementation.</li><li>Mechanism: the shared guard in <code>crates/recon-ui-guard-macos</code> watches the desktop for the whole of every guarded <code>ui</code> request and turns an observed interruption into <code>UI_INTERFERENCE</code>; when it cannot watch, the request fails with <code>INTERFACE_UNAVAILABLE</code> before it runs. <code>crates/recon/src/observe.rs</code> gives every request a guard scope except host preparation, and the command registry declares both errors for exactly the guarded commands. <code>mise run check</code> runs the guard&#39;s classification and scope tests; <code>mise run test:focus</code> runs the live evidence against the signed binary and the fixture.</li><li>Prose justification: not applicable. The live evidence is a task rather than a check because it needs a logged-in Mac with granted permissions and a desktop nobody is touching, which CI does not have.</li></ul><h2 id="how-to-comply" tabindex="-1">How to comply <a class="header-anchor" href="#how-to-comply" aria-label="Permalink to “How to comply”">​</a></h2><ol><li>Run every <code>ui</code> operation that inspects or acts on an application inside the shared guard; do not add a route around it.</li><li>Design each operation&#39;s mechanism in its proposal and show with live evidence that the person is not interrupted. This policy neither allows nor forbids a mechanism except through that evidence.</li><li>When an operation cannot do its work without interrupting the person, refuse with a typed reason rather than interrupting and restoring, or presenting an incomplete result as complete.</li><li>Exempt a new command only when it acts on no application and its interruptions are setup the operator asked for; record the exemption here first.</li><li>Run <code>mise run check</code>. For a change to a live path, also run <code>mise run test:focus</code> hands-off and record the evidence in the readiness report.</li></ol><h2 id="revision-history" tabindex="-1">Revision history <a class="header-anchor" href="#revision-history" aria-label="Permalink to “Revision history”">​</a></h2><table tabindex="0"><thead><tr><th>Date</th><th>Change</th><th>Authority</th></tr></thead><tbody><tr><td>2026-11-07</td><td>Established, superseding policy.0004: states the behaviour the person experiences instead of the mechanisms that preserve it.</td><td>Owner direction</td></tr></tbody></table>`,17)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};